sksl:
#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0)); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);return float4(0.0); }
uniform float amzp_amount;
uniform float amzp_speed;
uniform float amzp_seed;
uniform float amzp_noise;
uniform float amzp_noiseSize;
uniform float amzp_noiseColor;
uniform float amzp_scan;
uniform float amzp_scanSpacing;
uniform float amzp_roll;
uniform float amzp_rollBar;
uniform float amzp_jitter;
uniform float amzp_wave;
uniform float amzp_waveFreq;
uniform float amzp_tear;
uniform float amzp_tearShift;
uniform float amzp_bleed;
uniform float amzp_chroma;
uniform float amzp_ghost;
uniform float amzp_ghostOffset;
uniform float amzp_sat;
uniform float amzp_flicker;
uniform float amzp_vignette;
uniform float amzp_mixAmt;
uniform float amzp_overdrawOn;
uniform float amzp_quality;
    float qMul() { return amzp_quality < 1.5 ? 0.25 : (amzp_quality < 2.5 ? 0.5 : (amzp_quality < 3.5 ? 1.0 : (amzp_quality < 4.5 ? 1.5 : 2.0))); }
    float2 l2s(float2 v) { return (float4(v, 0.0, 1.0) * amzLayerToScreen()).xy; }
    float h1(float x) { return fract(sin(x * 91.345 + amzp_seed * 13.7) * 43758.5453); }
    float h2(float2 p) { return fract(sin(dot(p, float2(127.1, 311.7)) + amzp_seed * 3.91) * 43758.5453); }
    float vn(float x) { float i = floor(x), f = fract(x); f = f * f * (3.0 - 2.0 * f); return mix(h1(i), h1(i + 1.0), f); }
    float2 W;
    float4 at(float2 px) {
        float2 uv = px / W;
        uv.y = fract(uv.y);
        if (uv.x < 0.0 || uv.x > 1.0) return float4(0.0);
        return amzTexture(0, l2s(uv));
    }
    float3 unp(float4 c) { return c.a > 0.0001 ? c.rgb / c.a : float3(0.0); }
    float3 toYiq(float3 c) { return float3(dot(c, float3(0.299, 0.587, 0.114)), dot(c, float3(0.596, -0.274, -0.322)), dot(c, float3(0.211, -0.523, 0.312))); }
    float3 toRgb(float3 y) { return float3(y.x + 0.956 * y.y + 0.621 * y.z, y.x - 0.272 * y.y - 0.647 * y.z, y.x - 1.106 * y.y + 1.703 * y.z); }
    void nmMain() {
        W = layer;
        float px = screen.zw.x / max(screen.zw.x, 1.0);
        float A = max(amzp_amount, 0.0);
        float T = time * max(amzp_speed, 0.0);
        float2 uv = amzLayerNorm();
        float4 src = amzTexture(0, l2s(uv));
        float ry = uv.y + time * amzp_roll * 0.25;
        float yy = fract(ry);
        float bar = smoothstep(0.0, 0.035, yy) * smoothstep(0.0, 0.035, 1.0 - yy);
        float2 p = float2(uv.x, yy) * W;
        float line = floor(p.y / max(2.0 * px, 1.0));
        float fr = floor(T * 24.0);
        float spike = step(0.93, h1(fr * 1.7 + 3.0));
        float dx = (h1(line * 0.37 + fr) - 0.5) * amzp_jitter * px * A * (0.35 + 1.65 * spike * h1(line * 0.11 + fr * 0.5));
        dx += sin(yy * amzp_waveFreq * 6.2831 + T * 3.1 + amzp_seed) * amzp_wave * px * A * (0.6 + 0.4 * vn(T * 0.7 + yy * 3.0));
        float tc = fract(T * 0.11 + h1(7.0) );
        float bw = 0.06 + 0.05 * vn(T * 0.5);
        float d = abs(yy - tc);
        d = min(d, 1.0 - d);
        float band = clamp(1.0 - d / bw, 0.0, 1.0);
        dx += band * band * amzp_tearShift * px * clamp(amzp_tear, 0.0, 1.0) * A * (0.6 + 0.8 * vn(yy * 60.0 + T * 5.0));
        p.x += dx;
        float4 c0 = at(p);
        float3 yiq = toYiq(unp(c0));
        float bl = amzp_bleed * px * A;
        float3 ch = float3(0.0);
        float nTap = max(3.0, floor(7.0 * qMul() + 0.5));
        for (int i = 0; i < 14; i++) {
            if (float(i) >= nTap) break;
            float4 s = at(p + float2((float(i) / (nTap - 1.0) * 2.0 - 1.0) * bl + amzp_chroma * px * A, 0.0));
            ch += toYiq(unp(s));
        }
        ch /= nTap;
        float3 col = toRgb(float3(yiq.x, ch.y, ch.z));
        float a = c0.a;
        float4 g = at(p + float2(amzp_ghostOffset * px, 0.0));
        col += unp(g) * clamp(amzp_ghost, 0.0, 1.0) * A * 0.6 * g.a;
        a = max(a, g.a * clamp(amzp_ghost * A, 0.0, 1.0) * 0.6);
        float l = dot(col, float3(0.299, 0.587, 0.114));
        col = mix(float3(l), col, max(amzp_sat, 0.0));
        float2 np = floor(amzLayerNorm() * W / max(amzp_noiseSize * px, 1.0));
        float nt = floor(time * 30.0 * max(amzp_speed, 0.05));
        float n = h2(np + nt * 17.0);
        float3 nc = float3(h2(np + nt * 17.0 + 3.1), h2(np + nt * 17.0 + 7.3), h2(np + nt * 17.0 + 11.9));
        float3 snow = mix(float3(n), nc, clamp(amzp_noiseColor, 0.0, 1.0));
        float na = clamp(amzp_noise * A, 0.0, 1.0);
        col = mix(col, snow, na * 0.55) + (snow - 0.5) * na * 0.25;
        float sl = 0.5 + 0.5 * cos(amzLayerNorm().y * W.y / max(amzp_scanSpacing * px, 1.0) * 6.2831);
        col *= 1.0 - clamp(amzp_scan * A, 0.0, 1.0) * (1.0 - sl) * 0.8;
        col *= 1.0 + (vn(T * 12.0) - 0.5) * clamp(amzp_flicker, 0.0, 1.0) * A * 0.7;
        col *= mix(1.0, bar, clamp(amzp_rollBar, 0.0, 1.0) * step(0.001, abs(amzp_roll)));
        float2 v = amzLayerNorm() - 0.5;
        col *= 1.0 - clamp(amzp_vignette, 0.0, 1.0) * smoothstep(0.25, 0.75, length(v * float2(1.0, W.y / max(W.x, 1.0)) * 1.2));
        float4 outc = float4(clamp(col, 0.0, 1.0) * a, a);
        amzOutput = mix(src, outc, clamp(amzp_mixAmt, 0.0, 1.0));
    }
    void amzRender() {
        nmMain();
        if (!(amzp_overdrawOn>0.5)) amzOutput *= amzTexture(0, amzScreenNorm()).a;
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }
